    let predicate = "block_number IN (1, 2, 3, 4, 5, 6) \
                     AND block_number NOT IN (1, 2, NULL)";
    let result = execute_sql(
        &format!(
            "SELECT SUM(CASE WHEN {predicate} THEN data ELSE 0 END) AS total \
             FROM logs WHERE data_len = 32"
